(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.016+t*0.38)*11;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025-t*0.5)*8 + Math.cos(sy*0.02+t*0.45)*6;
  const w2y = Math.cos(sy*0.022+t*0.48)*7 + Math.sin(sx*0.019-t*0.52)*5;
  const wx = sx + w2x, wy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*110, 80+Math.cos(t*0.4)*55, 0.075, 2.1],
    [320+Math.cos(t*0.5)*105, 160+Math.sin(t*0.7)*55, 0.095, 1.8],
    [240+Math.sin(t*0.3+2)*145, 120+Math.cos(t*0.5+1)*95, 0.055, 2.4],
    [120+Math.cos(t*0.8+1)*85, 180+Math.sin(t*0.6+3)*65, 0.115, 1.6],
    [360+Math.sin(t*0.4+4)*95, 60+Math.cos(t*0.9+2)*75, 0.065, 2.7],
    [240+Math.cos(t*0.35+5)*125, 200+Math.sin(t*0.55)*85, 0.085, 2.0],
    [80+Math.sin(t*0.55+3)*70, 40+Math.cos(t*0.65+2)*60, 0.13, 1.4],
    [400+Math.cos(t*0.45+1)*80, 220+Math.sin(t*0.75+4)*50, 0.07, 2.8],
    [200+Math.sin(t*0.7+5)*60, 230+Math.cos(t*0.5+3)*40, 0.1, 1.9]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((wx-sX)**2+(wy-sY)**2);
    const d2 = Math.sqrt((wx-sX*0.5-cx*0.5)**2+(wy-sY*0.5-cy*0.5)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2 += Math.sin(d2*f*1.5-t*sp*0.8+0.8);
    iS2 += Math.cos(d2*f*1.2+t*sp*0.5-1.2);
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, act2 = aS2/n, inh2 = iS2/n;
  const bg = (Math.sin(wx*0.035+wy*0.022+t*0.9)+Math.sin(wx*0.028-wy*0.038+t*1.2))/2
    + Math.sin((wx+wy)*0.11+t*2.8)*0.2 + Math.sin((wx-wy)*0.09-t*2.2)*0.2;
  const dist = Math.sqrt((wx-cx)**2+(wy-cy)**2), ang = Math.atan2(wy-cy, wx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.6)+Math.sin(dist*0.035+ang*4.5-t*1.3))*0.35;
  const spiral2 = Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const react1 = Math.tanh((act-inh*0.65+bg*0.3+spiral)*2.4);
  const react2 = Math.tanh((act2*0.6-inh2*0.5+spiral2+react1*0.4)*2.0);
  const cell = Math.tanh((Math.sin(wx*0.14)*Math.sin(wy*0.14)+Math.sin((wx+wy)*0.09+t)*0.5)*1.6)*0.25;
  const vein = (Math.sin(ang*6+dist*0.03-t*0.8)+Math.sin(ang*4-dist*0.04+t*1.1))*0.12*Math.max(0,1-dist*0.004);
  const micro = Math.sin(wx*0.3+t*3)*Math.sin(wy*0.28-t*2.7)*0.08;
  const blend = react1*0.5+react2*0.25+cell*0.15+vein*0.05+micro*0.05;
  const v = blend*0.5+0.5;
  const pulse = 0.92+Math.sin(t*0.4)*0.08;
  const pal = [
    [12,22,72],[18,55,105],[20,95,128],[25,140,135],[45,168,115],
    [120,185,75],[195,185,60],[215,150,55],[210,105,65],[180,60,60],
    [130,35,70],[75,22,55],[12,22,72]
  ];
  const idx = v*(pal.length-1)*pulse, i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.78+Math.sin(react1*Math.PI)*0.22;
  const edge = Math.abs(react1)>0.65?1.18:Math.abs(react2)>0.6?1.08:1.0;
  const depth = 0.95+react2*0.05;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*depth)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*depth)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*depth)|0
  ];
}
